THEN
ItemRotateY((ITEM)S_LOW_DevilsFee_Cellar_Bust_92e9d1a9-189b-42f7-9025-ba88f889eab7, 90.0, 90.0);
NOT DB_LOW_DevilsFee_CellarBustPosition(_Position);
